echo -e 'server {
  listen 8888;
  resolver 8.8.8.8;
  proxy_connect;
  proxy_connect_allow all;
  location / { proxy_pass http://$host; }
}' > /etc/nginx/sites-available/forward-proxy && nginx -s reload

echo -e 'location /static/ {
  gzip on;
  gzip_types text/css application/javascript image/svg+xml;
  gzip_min_length 1000;
}' >> /etc/nginx/sites-available/default && nginx -s reload
